/* Generated by Trae Work */
/* 自考专区渲染：课程卡（官方大纲知识点 / 笔记考点）+ 真题列表 + 笔记 + 考试安排 */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    const Z = SITE_DATA.zikao;
    const DEEP = window.DEEP || { syllabus: {}, notes: {} };

    /* 新旧代码对照 */
    const ocg = document.getElementById("oldcode-grid");
    Z.old_code_map.forEach(m => {
      const d = h("div", { class: "card" });
      d.innerHTML = `<h3>${m.new_code} ↔ ${m.old_code}</h3><p class="muted">${m.note}</p>`;
      ocg.appendChild(d);
    });

    /* ---------- 知识点渲染 ---------- */
    function paperCount(code) { return Z.papers.filter(p => p.course_code === code).length; }

    function syllabusHtml(c, s) {
      /* s = DEEP.syllabus[code]：章 → 目的要求 / 教学内容 / 考核知识点（含识记领会层次） */
      const ptTotal = s.chapters.reduce((n, ch) => n + ch.points.length, 0);
      const head = `
        <div class="notice info">以下"目的要求 / 教学内容 / 考核知识点"逐字取自<a href="${s.syllabus_url || c.syllabus_url}" target="_blank" rel="noopener">官方考试大纲（.doc 原文）</a>，解析于 ${c.syllabus_verified_at || SITE_DATA.meta.built_at}。OCR 识别可能存在个别缺字，以大纲原文为准。${c.syllabus_note || ""}</div>
        <details class="chapters"><summary>展开官方大纲知识点（${s.chapters.length} 章 · 考核知识点 ${ptTotal} 条）</summary>
          <ol class="deep-chapters">`;
      const body = s.chapters.map(ch => {
        const purpose = ch.purpose.length ? `
            <div class="dp-block"><span class="dp-label">目的要求</span>
              <ul>${ch.purpose.map(t => `<li>${t}</li>`).join("")}</ul></div>` : "";
        const secs = ch.sections.length ? `
            <div class="dp-block"><span class="dp-label">教学内容</span>
              <ul>${ch.sections.map(t => `<li>${t}</li>`).join("")}</ul></div>` : "";
        const pts = ch.points.length ? `
            <div class="dp-block"><span class="dp-label">考核知识点</span>
              <ul>${ch.points.map(p => `<li>${p.text}${p.subs && p.subs.length ? `<ul class="dp-subs">${p.subs.map(t => `<li>${t}</li>`).join("")}</ul>` : ""}</li>`).join("")}</ul></div>` : "";
        const note = ch.note ? `<div class="dp-note">${ch.note}</div>` : "";
        return `<li><strong>${ch.title}</strong>${purpose}${secs}${pts}${note}</li>`;
      }).join("");
      return head + body + `</ol></details>`;
    }

    function notesHtml(c, n) {
      /* n = DEEP.notes[code]：公开笔记的"考点"结构（个人整理，未经官方审核） */
      const ptTotal = n.chapters.reduce((a, ch) => a + ch.points.length, 0);
      return `
        <div class="notice ref"><strong>可背诵考点（个人笔记，未经官方审核）。</strong>${c.ref_note || ""}<br>
          来源：<a href="${n.source_url}" target="_blank" rel="noopener">${n.source_platform}</a>（verified_at ${n.verified_at}）。${n.note}</div>
        <details class="chapters"><summary>展开笔记考点（${n.chapters.length} 组 · ${ptTotal} 条）</summary>
          <ol class="deep-chapters">${n.chapters.map(ch => `
            <li><strong>${ch.title}</strong>
              <div class="dp-block"><span class="dp-label">考点</span>
                <ul>${ch.points.map(t => `<li>${t}</li>`).join("")}</ul></div>
            </li>`).join("")}</ol></details>`;
    }

    /* ---------- 课程网格 ---------- */
    const cg = document.getElementById("course-grid");
    Z.courses.forEach(c => {
      const s = DEEP.syllabus[c.code];
      const n = DEEP.notes[c.code];
      const card = h("div", { class: "course-card", id: `course-${c.code}` });
      const pCount = paperCount(c.code);
      let inner = `
        <div class="cc-head"><span class="cc-code">${c.code}</span><span class="badge code">${c.kind}</span>
          ${c.old_code ? `<span class="cc-old">旧代码 ${c.old_code}</span>` : ""}</div>
        <div class="cc-name">${c.name}</div>
        <div class="cc-status">
          ${s ? `<span class="badge ok">官方大纲知识点</span>` : n ? `<span class="badge warnb">笔记考点</span>` : `<span class="badge miss">大纲暂缺</span>`}
          <a href="past-papers.html" class="badge ${pCount ? "ok" : "miss"}" style="text-decoration:none;">真题 ${pCount} 套</a>
        </div>`;
      if (s) {
        inner += syllabusHtml(c, s);
      } else if (n) {
        inner += notesHtml(c, n);
      } else if (c.reference_chapters) {
        inner += `
          <div class="notice ref"><strong>参考结构，非官方大纲。</strong>${c.ref_note}<br>
            来源：<a href="${c.reference_chapters.source_url}" target="_blank" rel="noopener">${c.reference_chapters.source_platform}</a>
            （verified_at ${c.reference_chapters.verified_at}）</div>
          <details class="chapters"><summary>展开参考章节（${c.reference_chapters.chapters.length} 章）</summary>
            <ul class="chapter-list">${c.reference_chapters.chapters.map(t => `<li>${t}</li>`).join("")}</ul>
          </details>`;
      } else {
        inner += `<div class="notice empty"><strong>暂无可背诵知识点。</strong>该课程既未检索到官方考试大纲，也没有可追溯的按章节组织的公开笔记；本页不以商业考点汇总填充。可先在<a href="past-papers.html">历年真题页</a>查看该课程已收录真题${c.kind !== "笔试" ? "（实践/论文类课程无笔试知识点）" : ""}。</div>`;
      }
      card.innerHTML = inner;
      cg.appendChild(card);
    });

    /* ---------- 真题收录（列表 + 入口） ---------- */
    const pp = document.getElementById("zikao-papers");
    if (Z.papers.length === 0) {
      pp.innerHTML = `<div class="notice empty"><strong>暂无已收录真题。</strong>${Z.papers_note || Z.papers_empty_note || ""}</div>`;
    } else {
      pp.innerHTML = `
        <div class="notice info">已收录 <strong>${Z.papers.length}</strong> 套来源可追溯的原始真题，逐条标注平台与完整 URL；完整汇总见<a href="past-papers.html">历年真题合计页</a>。</div>
        <div class="grid grid-2">${Z.papers.map(p => `
          <div class="card paper-card">
            <div class="p-title">${p.title}</div>
            <p class="muted">来源平台：${p.source_platform} · 收录快照：${p.crawled_at}</p>
            <p class="src" style="margin-top:6px;">来源：<a href="${p.source_url}" target="_blank" rel="noopener">${p.source_url}</a></p>
          </div>`).join("")}</div>
        <p class="desc" style="margin-top:10px;">${Z.papers_note}</p>`;
    }

    /* ---------- 笔记 ---------- */
    const ng = document.getElementById("zikao-notes");
    Z.notes.forEach(n => {
      const d = h("div", { class: "card" });
      d.innerHTML = `
        <h3>${n.title} <span class="badge zikao">${n.course_code}</span></h3>
        <p class="muted">来源平台：${n.source_platform} · 来源类型：${n.source_type === "personal_note" ? "个人笔记（未经官方审核）" : n.source_type} · 收录快照：${n.crawled_at}</p>
        <p style="font-size:13.5px;margin-top:6px;">${n.note}</p>
        <p class="src" style="margin-top:8px;">完整 URL：<a href="${n.source_url}" target="_blank" rel="noopener">${n.source_url}</a></p>`;
      ng.appendChild(d);
    });

    /* ---------- 考试安排 ---------- */
    const er = document.getElementById("zikao-exam-rules");
    const R = Z.exam_rules;
    er.innerHTML = `
      <h3>黑龙江自考考试规则</h3>
      <ul style="font-size:14px;line-height:2;margin-top:8px;">
        <li>考期：${R.sessions_per_year}</li>
        <li>每日时段：${R.daily_slots}</li>
        <li>每次最多报考：${R.max_subjects_per_session} 门</li>
      </ul>
      <p class="src">来源：<a href="${R.source_url}" target="_blank" rel="noopener">${R.source_url}</a> · verified_at ${R.verified_at}</p>
      <hr class="rule">
      <p style="font-size:13.5px;">2027 年及之后的考期尚未公布，页面显示“待官方公布”，不写死日期。倒计时仅在存在已核验 confirmed 日期时显示（见<a href="index.html">首页</a>与<a href="timeline.html">时间线</a>）。</p>`;
  });
})();
